with open('scores.txt', 'r') as f:
    count = 0
    for line in f:
        stripped = line.strip()
        if not stripped:
            continue
        try:
            score = int(stripped)
        except ValueError:
            continue
        if 0 <= score <= 100:
            count += 1
print('Valid scores:', count)

def read_lines(filename, encoding='utf-8'):
    with open(filename, 'r', encoding=encoding) as f:
        for line in f:
            yield line.rstrip('\n')

filename = 'data.txt'

try:
    with open(filename, 'r') as file:
        for line in file:
            print(line, end='')
except FileNotFoundError:
