filename = 'config.txt'

config = {}
with open(filename, 'r') as file:
    for line in file:
        line = line.strip()
        if not line or '=' not in line:
            continue
        key, value = line.split('=', 1)
        config[key.strip()] = value.strip()

print(config)

filename = 'log.txt'

error_count = 0
try:
    with open(filename, 'r') as file:
        for line in file:
            if line.lstrip().startswith('[ERROR]'):
                error_count += 1
    print(error_count)
except PermissionError:
    print('Access denied')

filename = 'inventory.csv'

inventory = {}
with open(filename, 'r') as file:
    for line in file:
        parts = line.strip().split(',')
        if len(parts) != 3:
            continue
        pid, name, qty = parts
        try:
            qty = int(qty)
        except ValueError:
            continue
        inventory[pid.strip()] = (name.strip(), qty)

print(inventory)

def read_and_validate(filename):
    try:
        with open(filename, 'r') as file:
            lines = [line.strip() for line in file if line.strip()]
    except FileNotFoundError:
        raise FileNotFoundError(f'The file {filename} does not exist.')
    except PermissionError:
        raise PermissionError(f'Permission denied for {filename}.')

    if not lines:
        raise ValueError('The file is empty or contains only whitespace.')

    return lines
